{
  "name": "opencode-planner",
  "version": "0.6.0",
  "description": "OpenCode plugin emulating Experimental Planning Mode and sending plan to configured editor for acceptance or editing",
  "type": "module",
  "main": "./index.js",
  "author": "Tim Richardson",
  "exports": {
    ".": "./index.js",
    "./server": "./server.js"
  },
  "files": [
    "index.js",
    "server.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test",
    "test:integration:v1": "node scripts/check-v1-runtime.js",
    "test:integration:v2": "node scripts/check-v2-plan-workflow.js",
    "debug:plan": "node scripts/debug-plan-runtime.js",
    "opencode:no-plannotator": "node scripts/run-opencode-sandbox.js --without-plannotator"
  },
  "keywords": [
    "opencode",
    "plugin",
    "planning",
    "agent"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/timrichardson/opencode-planner.git"
  },
  "homepage": "https://github.com/timrichardson/opencode-planner#readme",
  "bugs": {
    "url": "https://github.com/timrichardson/opencode-planner/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "license": "MIT"
}
